      '<p class="b-chips">' + r.chips.map(function (c) { return C.chip(c, ''); }).join('') + '</p>' +
      (r.excluded ? '<p class="b-risk">' + C.icon('lock') + esc(r.reason) + '. Un score élevé ne lève pas une contrainte ferme.' + (r.raw != null ? ' Score brut ' + r.raw + '.' : '') + '</p>' : '') + (m.cautions[b.id] ? '<p class="b-risk">' + C.icon('alert') + esc(m.cautions[b.id]) + '</p>' : '') +
      (x.refused ? '<p class="b-risk">' + C.icon('x') + 'A décliné le ' + U.date(x.refused.date) + ' : ' + esc(x.refused.reason) + '. Reste admissible pour d’autres dossiers.</p>' : '') +
      '<table class="mini"><tbody>' + r.parts.map(function (p) { return '<tr><th scope="row">' + esc(p.label) + '</th><td class="num">' + p.sub + ' × ' + p.w + ' %</td><td class="num">' + U.num(p.pts, 1) + '</td></tr>'; }).join('') + '</tbody></table><p class="cell-sub">Thèse : ' + esc(b.thesis) + '</p>' + (learned.length ? '<p class="cell-sub">Critères appris (distincts des déclarés) : ' + esc(learned.join('; ')) + '</p>' : '') +
      (S.P.decideMandate() && !r.excluded && !nda ? C.btn('Exclure (cédant)', 'exclude-ask', { ui: true, small: true, variant: 'ghost', data: { m: m.id, id: b.id } }) : r.excluded && S.P.decideMandate() ? C.btn('Lever l’exclusion', 'exclusionSet', { small: true, variant: 'ghost', data: { m: m.id, id: b.id, reason: '' } }) : '');
